use super::net;
use crate::{config::CustomTarget,state::Sample};
pub async fn check(client:&reqwest::Client,targets:&[CustomTarget])->Vec<Sample>{let mut futs=Vec::new();for t in targets.iter().filter(|t|t.enabled).cloned(){let c=client.clone();futs.push(tokio::spawn(async move{let group=if t.domestic{"custom_domestic"}else{"custom_international"};let ms=match t.kind.as_str(){"http"=>{let url=if t.host.starts_with("http"){t.host.clone()}else{format!("https://{}",t.host)};net::http(&c,&url,net::T).await},"icmp"=>match resolve(&t.host,t.port).await{Some(a)=>net::ping(a.ip(),t.port).await,None=>None},_=>match resolve(&t.host,t.port).await{Some(a)=>net::tcp(a).await,None=>None}};Sample{name:t.name.clone(),proto:t.kind.clone(),group:group.into(),ok:ms.is_some(),ms}}));}let mut out=Vec::new();for f in futs{if let Ok(s)=f.await{out.push(s)}}out}
async fn resolve(host:&str,port:u16)->Option<std::net::SocketAddr>{tokio::time::timeout(net::T,tokio::net::lookup_host((host,port))).await.ok()?.ok()?.next()}
